package net.nuggetmc.tplus.compat.bukkit.entity;
import net.nuggetmc.tplus.compat.bukkit.inventory.meta.FireworkMeta;
public class Firework extends Entity { public Firework(net.minecraft.world.entity.Entity e){super(e);} private FireworkMeta meta=new FireworkMeta();private Object shooter;private int ticks;public void detonate() { handle.discard(); }public FireworkMeta getFireworkMeta(){return meta.clone();}public void setFireworkMeta(FireworkMeta m){meta=m;}public void setShooter(Object s){shooter=s;}public Object getShooter(){return shooter;}public void setTicksToDetonate(int t){ticks=t;}public int getTicksToDetonate(){return ticks;} }
